-- prado-privacy schema for mysql; generated from TPrivacySchema.
CREATE TABLE IF NOT EXISTS privacy_consent_log (id BIGINT UNSIGNED NOT NULL AUTO_INCREMENT PRIMARY KEY, consent_id VARCHAR(32) NOT NULL, created_at BIGINT NOT NULL, version VARCHAR(64) NOT NULL, categories TEXT NOT NULL, source VARCHAR(16) NOT NULL, region VARCHAR(8) NULL, gpc SMALLINT NOT NULL DEFAULT 0, ip_hash CHAR(64) NULL, subject_hash CHAR(64) NULL, user_agent_hash CHAR(64) NULL, INDEX idx_privacy_consent_log_consent (consent_id), INDEX idx_privacy_consent_log_created (created_at), INDEX idx_privacy_consent_log_subject (subject_hash)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS privacy_consent_state (consent_id VARCHAR(32) NOT NULL PRIMARY KEY, subject_hash CHAR(64) NULL, categories TEXT NOT NULL, version VARCHAR(64) NOT NULL, source VARCHAR(16) NOT NULL, updated_at BIGINT NOT NULL, expires_at BIGINT NOT NULL, INDEX idx_privacy_consent_state_subject (subject_hash), INDEX idx_privacy_consent_state_expires (expires_at)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
